-- Grape notes, round 4, strong part (product owner, 2026-11-23: "Ga door met ronde 4: de overige landen
-- (Zwitserland, Griekenland, Kroatië, Roemenië, Hongarije en de rest)"). 145 fields.
-- Two independent organisations per claim.
-- Region statements fill only fields still empty in production and stop
-- the whole file if any field was no longer empty; local_note is then
-- rewritten from the three fields for builds up to 1.9.0 (48). Keyed on
-- ids, never on names. Sources per row: round4_*.csv beside this file.
begin;
create temp table round4_hit (region_id uuid, grape_id uuid) on commit drop;
